// La palabra clave abstract antes de class la hace abstracta
public abstract class Enemy
{
    public string EnemyName;
    public int Health;

    public Enemy(string name, int health)
    {
        EnemyName = name;
        Health = health;
    }

    // Método concreto: tiene implementación, todas las clases derivadas lo heredan
    public void Die()
    {
        Debug.Log(EnemyName + " has been defeated!");
    }

    // Método abstracto: NO tiene cuerpo (sin {}), DEBE ser implementado en clases derivadas
    public abstract void Attack();

    public abstract void TakeDamage(int dmg);
}

// Goblin DEBE implementar todos los métodos abstractos
public class Goblin : Enemy
{
    public Goblin(string name) : base(name, 50) { }

    public override void Attack()
    {
        Debug.Log(EnemyName + " stabs for 8 damage!");
    }

    public override void TakeDamage(int dmg)
    {
        Health -= dmg;
        Debug.Log(EnemyName + " takes " + dmg + " damage. HP: " + Health);
    }
}

