public abstract class Vehicle
{
    public int Speed;

    public abstract void Move();

    public void Refuel()
    {
        Debug.Log("Refueling...");
    }
}

public abstract class Shape
{
    public abstract float CalculateArea();
}

public class Circle : Shape
{
    public float Radius;
    // No implementa CalculateArea()
}

public abstract class EnemyBase : MonoBehaviour
{
    public int Health = 100;

    public abstract void TakeDamage(int dmg);
    public abstract void Attack();

    public void Die()
    {
        Destroy(gameObject);
    }
}

public class SkeletonEnemy : EnemyBase
{
    public override void TakeDamage(int dmg) { Health -= dmg; }
    public override void Attack() { Debug.Log("Skeleton attacks!"); }
}

public abstract class Animal
{
    public abstract void MakeSound();
}

public abstract class Pet : Animal
{
    public string OwnerName;
    // No implementa MakeSound()
}

public class Dog : Pet
{
    public override void MakeSound()
    {
        Debug.Log("Woof!");
    }
}

public abstract class Spell
{
    public string SpellName;
    public int ManaCost;

    public Spell(string name, int mana)
    {
        SpellName = name;
        ManaCost = mana;
    }

    public abstract void Cast(GameObject target);
}

public abstract class Collectible : MonoBehaviour
{
    public abstract void OnCollect(GameObject player);

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            OnCollect(other.gameObject);
            Destroy(gameObject);
        }
    }
}

